// cgoa_progress.h
typedef void (*progress_cb)(size_t i, size_t total, void* ctx);
int process_batch(const int* input, size_t n, int op_code, progress_cb cb, void* ctx, int* out_result);
```
```c
// cgoa_progress.c
#include "cgoa_progress.h"
#include <stdlib.h>
static inline void call_progress(progress_cb cb, size_t i, size_t total, void* ctx){ if(cb) cb(i, total, ctx); }
int process_batch(const int* input, size_t n, int op_code, progress_cb cb, void* ctx, int* out_result){ int sum=0; for(size_t i=0;i<n;i++){ int v=input[i]; if(op_code==0) v=-v; else if(op_code==1) v+=1; else if(op_code==2) v*=2; sum+=v; if(n>0 && (i+1)*10>=n){ call_progress(cb, i+1, n, ctx); } } *out_result=sum; return 0; }
```
```go
// cgoa_progress.go
package main
/*
#include "cgoa_progress.h"
extern void goProgressCallback(uintptr_t ctx, size_t i, size_t total);
static inline void trampoline_progress(size_t i, size_t total, void* ctx){ goProgressCallback((uintptr_t)ctx, i, total); }
*/
import "C"
import (
  "fmt"
  "unsafe"
)
var progRegs = map[uintptr]chan int{}
//export goProgressCallback
func goProgressCallback(ctx C.uintptr_t, i C.size_t, total C.size_t) {
  if ch, ok := progRegs[uintptr(ctx)]; ok {
    ch <- int(i)
  }
}
func ProcessBatch(input []int, opCode int) (int, error) {
  // setup
  cInput := make([]C.int, len(input))
  for idx, v := range input { cInput[idx] = C.int(v) }
  var out C.int
  ctx := uintptr(unsafe.Pointer(&input))
  ch := make(chan int, 100)
  progRegs[ctx] = ch
  go func(){ for p := range ch { fmt.Println("progress:", p) } }()
  C.process_batch((*C.int)(&cInput[0]), C.size_t(len(input)), C.int(opCode), C.trampoline_progress, unsafe.Pointer(ctx), &out)
  delete(progRegs, ctx)
  return int(out), nil
}
```

